@Override
    public List<EntityAuditEventV2> deleteEventsV2(String entityId,
            Set<EntityAuditEventV2.EntityAuditActionV2> entityAuditActions,
            short allowedAuditCount,
            int ttlInDays,
            boolean createEventsAgeoutAllowed,
            Constants.AtlasAuditAgingType auditAgingType) throws AtlasBaseException {
        AtlasPerfMetrics.MetricRecorder metric = RequestContext.get().startMetricRecord("deleteEventsV2");

        try (RdbmsTransaction trx = new RdbmsTransaction()) {
            DbEntityAuditDao dao = new DbEntityAuditDao(trx.getEntityManager());
            List<EntityAuditEventV2> deletedEvents = new ArrayList<>();

            boolean allowAgeoutByAuditCount = allowedAuditCount > 0 || (auditAgingType == Constants.AtlasAuditAgingType.SWEEP);
            List<String> ageoutActionsNotAllowed = createEventsAgeoutAllowed ? Collections.emptyList() :
                    Arrays.asList(EntityAuditEventV2.EntityAuditActionV2.ENTITY_CREATE.name(),
                            EntityAuditEventV2.EntityAuditActionV2.ENTITY_IMPORT_CREATE.name());

            List<DbEntityAudit> eventsEligibleForAgeout = new ArrayList<>();
            List<DbEntityAudit> eventsToKeep = new ArrayList<>();

            if (CollectionUtils.isEmpty(entityAuditActions)) {
                List<DbEntityAudit> dbEvents = dao.getLatestAuditsByEntityIdAction(entityId, null, ageoutActionsNotAllowed);

                splitEventsToKeepAndAgeoutByAuditCount(dbEvents, allowAgeoutByAuditCount, allowedAuditCount, eventsToKeep, eventsEligibleForAgeout);
            } else {
                for (EntityAuditEventV2.EntityAuditActionV2 action : entityAuditActions) {
                    String actionName = action == null ? null : action.name();
                    List<DbEntityAudit> dbEvents = dao.getLatestAuditsByEntityIdAction(entityId, actionName, ageoutActionsNotAllowed);

                    splitEventsToKeepAndAgeoutByAuditCount(dbEvents, allowAgeoutByAuditCount, allowedAuditCount, eventsToKeep, eventsEligibleForAgeout);
                }
            }

            if (CollectionUtils.isNotEmpty(eventsToKeep)) {
                //Limit events based on configured audit count by grouping events of all action types
                if (allowAgeoutByAuditCount && (auditAgingType == Constants.AtlasAuditAgingType.DEFAULT || CollectionUtils.isEmpty(entityAuditActions))) {
                    LOG.debug("Aging out audit events by audit count for entity: {}", entityId);

                    eventsToKeep.sort((a, b) -> {
                        int cmp = Long.compare(b.getEventTime(), a.getEventTime());
                        if (cmp == 0) {
                            cmp = Integer.compare(b.getEventIndex(), a.getEventIndex());
                        }
                        return cmp;
                    });

                    if (allowedAuditCount < eventsToKeep.size()) {
                        eventsEligibleForAgeout.addAll(eventsToKeep.subList(allowedAuditCount, eventsToKeep.size()));
                        eventsToKeep = eventsToKeep.subList(0, allowedAuditCount);
                    }
                }

                //TTL based aging
                if (ttlInDays > 0) {
                    LOG.debug("Aging out audit events by TTL for entity: {}", entityId);

                    LocalDateTime now = LocalDateTime.now();
                    boolean isTTLTestAutomation = AtlasConfiguration.ATLAS_AUDIT_AGING_TTL_TEST_AUTOMATION.getBoolean();
                    long ttlTimestamp = Timestamp.valueOf(isTTLTestAutomation ? now.minusMinutes(ttlInDays) : now.minusDays(ttlInDays)).getTime();

                    eventsToKeep.forEach(e -> {
                        if (e.getEventTime() < ttlTimestamp) {
                            eventsEligibleForAgeout.add(e);
                        }
                    });
                }
            }

            Map<Long, DbEntityAudit> uniqueEligible = new LinkedHashMap<>();
            for (DbEntityAudit db : eventsEligibleForAgeout) {
                if (db != null && db.getId() != null) {
                    uniqueEligible.put(db.getId(), db);
                }
            }

            LOG.debug("Deleting events from audit table: {}", uniqueEligible.keySet());
            for (DbEntityAudit dbEvent : uniqueEligible.values()) {
                try {
                    trx.getEntityManager().remove(dbEvent);
                    deletedEvents.add(fromDbEntityAudit(dbEvent));
                } catch (Exception e) {
                    throw new AtlasBaseException("Failed to remove audit event: " + dbEvent, e);
                }
            }

            trx.commit();
            return deletedEvents;
        } catch (Exception e) {
            throw new AtlasBaseException("Error while deleting audit events", e);
        } finally {
            RequestContext.get().endMetricRecord(metric);
        }
    }

@Override
    void resolveReferences(AtlasTypeRegistry typeRegistry) throws AtlasBaseException {
        super.resolveReferences(typeRegistry);

        List<AtlasEntityType>       s    = new ArrayList<>();
        Set<String>                 allS = new HashSet<>();
        Map<String, AtlasAttribute> allA = new HashMap<>();

        getTypeHierarchyInfo(typeRegistry, allS, allA);

        for (String superTypeName : entityDef.getSuperTypes()) {
            AtlasType superType = typeRegistry.getType(superTypeName);

            if (superType instanceof AtlasEntityType) {
                s.add((AtlasEntityType) superType);
            } else {
                throw new AtlasBaseException(AtlasErrorCode.INCOMPATIBLE_SUPERTYPE, superTypeName, entityDef.getName());
            }
        }

        this.superTypes             = Collections.unmodifiableList(s);
        this.allSuperTypes          = Collections.unmodifiableSet(allS);
        this.allAttributes          = Collections.unmodifiableMap(allA);
        this.uniqAttributes         = getUniqueAttributes(this.allAttributes);
        this.subTypes               = new HashSet<>(); // this will be populated in resolveReferencesPhase2()
        this.allSubTypes            = new HashSet<>(); // this will be populated in resolveReferencesPhase2()
        this.typeAndAllSubTypes     = new HashSet<>(); // this will be populated in resolveReferencesPhase2()
        this.relationshipAttributes = new HashMap<>(); // this will be populated in resolveReferencesPhase3()
        this.businessAttributes     = new HashMap<>(); // this will be populated in resolveReferences(), from AtlasBusinessMetadataType
        this.tagPropagationEdges    = new HashSet<>(); // this will be populated in resolveReferencesPhase2()
        this.renamePropagationTargets              = new ArrayList<>(); // this will be populated in resolveReferencesPhase2()
        this.deletePropagationTargets              = new ArrayList<>(); // this will be populated in resolveReferencesPhase2()
        this.autoComputeFormatPathByRefTypeNameMap = new HashMap<>(); // this will be populated in resolveReferencesPhase3()

        this.typeAndAllSubTypes.add(this.getTypeName());

        this.typeAndAllSuperTypes = new HashSet<>(this.allSuperTypes);
        this.typeAndAllSuperTypes.add(this.getTypeName());
        this.typeAndAllSuperTypes = Collections.unmodifiableSet(this.typeAndAllSuperTypes);

        // headerAttributes includes uniqAttributes & ENTITY_HEADER_ATTRIBUTES
        this.headerAttributes = new HashMap<>(this.uniqAttributes);

        for (String headerAttributeName : ENTITY_HEADER_ATTRIBUTES) {
            AtlasAttribute headerAttribute = getAttribute(headerAttributeName);

            if (headerAttribute != null) {
                this.headerAttributes.put(headerAttributeName, headerAttribute);
            }
        }

        // minInfoAttributes includes all headerAttributes & schema-attributes
        this.minInfoAttributes = new HashMap<>(this.headerAttributes);

        Map<String, String> typeDefOptions       = entityDef.getOptions();
        String              jsonList             = typeDefOptions != null ? typeDefOptions.get(OPTION_SCHEMA_ATTRIBUTES) : null;
        List<String>        schemaAttributeNames = StringUtils.isNotEmpty(jsonList) ? AtlasType.fromJson(jsonList, List.class) : null;

        if (CollectionUtils.isNotEmpty(schemaAttributeNames)) {
            for (String schemaAttributeName : schemaAttributeNames) {
                AtlasAttribute schemaAttribute = getAttribute(schemaAttributeName);

                if (schemaAttribute != null) {
                    this.minInfoAttributes.put(schemaAttributeName, schemaAttribute);
                }
            }
        }

        if (this.displayTextAttribute != null) {
            if (getAttribute(this.displayTextAttribute) == null) {
                LOG.warn("{}: ignoring option {}, as attribute {} does not exist", getTypeName(), AtlasEntityDef.OPTION_DISPLAY_TEXT_ATTRIBUTE, this.displayTextAttribute);

                this.displayTextAttribute = null;
            }
        }

        if (this.displayTextAttribute == null) { // find displayTextAttribute in direct superTypes
            for (AtlasEntityType superType : superTypes) {
                // read from superType's entityDef; not from superType.getDisplayTextAttribute(), as that might have been resolved to its superType
                this.displayTextAttribute = superType.getEntityDef().getOption(AtlasEntityDef.OPTION_DISPLAY_TEXT_ATTRIBUTE);

                if (this.displayTextAttribute != null) {
                    if (getAttribute(this.displayTextAttribute) == null) { // if displayTextAttribute in superType is invalid, ignore
                        this.displayTextAttribute = null;
                    } else {
                        break;
                    }
                }
            }
        }
    }

